<?php use yii\helpers\Html; use yii\widgets\ActiveForm; $this->title = $model->full_name; ?>
<h1><?= Html::encode($this->title) ?></h1>
<?php if (!Yii::$app->user->isGuest): ?><p><?= Html::a('Редактировать', ['update', 'id' => $model->id], ['class' => 'btn btn-primary']) ?> <?= Html::a('Удалить', ['delete', 'id' => $model->id], ['class' => 'btn btn-danger', 'data' => ['method' => 'post', 'confirm' => 'Удалить автора?']]) ?></p><?php endif; ?>
<h2 class="h4">Книги</h2><ul><?php foreach ($model->books as $book): ?><li><?= Html::a(Html::encode($book->title), ['/book/view', 'id' => $book->id]) ?> (<?= $book->publication_year ?>)</li><?php endforeach; ?></ul>
<div class="card mt-4"><div class="card-body"><h2 class="h5">Подписаться на новые книги этого автора</h2><?php $form = ActiveForm::begin(['action' => ['subscribe', 'id' => $model->id]]); ?><?= $form->field($subscription, 'email')->input('email') ?><?= Html::submitButton('Подписаться', ['class' => 'btn btn-success']) ?><?php ActiveForm::end(); ?></div></div>
